async function dcSet(id,azione,fino){const r=await api({action:"dec_set",id,azione,fino});if(r&&r.ok){DC.dec=r.dec;DCT=null;dcRender()}else alert("Non salvato: "+((r&&r.error)||""))}
document.getElementById("dc").addEventListener("click",async e=>{const fr=e.target.closest("[data-fb-rep]");if(fr){const id=fr.dataset.fbRep;if(FBREP[id])delete FBREP[id];else FBREP[id]=true;dcRender();const t=document.getElementById("fbr-"+id);if(t)t.focus();return}const fs=e.target.closest("[data-fb-send]");if(fs){const id=fs.dataset.fbSend,t=document.getElementById("fbr-"+id),v=(t&&t.value||"").trim();if(v.length<2){alert("Scrivi la risposta.");return}const x=(DC.fb||[]).find(y=>y.id===id);if(!confirm("Inviare la risposta a "+(x&&x.email)+" da hello@readgeopolitics.com?"))return;FBREP[id]=v;fs.disabled=true;fs.textContent="Invio…";const r=await api({action:"fb_reply",id,testo:v});if(r&&r.ok){delete FBREP[id];DC.fb=r.items;dcRender()}else{fs.disabled=false;fs.textContent="Invia risposta";alert("Non inviata: "+((r&&r.error)||""))}return}const fl=e.target.closest("[data-fb-load]");if(fl){fl.disabled=true;fl.textContent="Carico…";const r=await api({action:"fb_img",id:fl.dataset.fbLoad});if(r&&r.ok){FBIMG[fl.dataset.fbLoad]=r.img;dcRender()}else{fl.textContent="Non trovata"}return}const fi=e.target.closest(".fb-im img");if(fi){window.open(fi.src,"_blank");return}const fm=e.target.closest("[data-fb-more]");if(fm){FBMORE=true;dcRender();return}const fb=e.target.closest("[data-fb]");if(fb){fb.disabled=true;const r=await api({action:"fb_set",id:fb.dataset.fb,stato:fb.dataset.fbS});if(r&&r.ok){DC.fb=r.items;dcRender()}else{fb.disabled=false;alert("Non salvato: "+((r&&r.error)||""))}return}const m=e.target.closest("[data-dc-more]");if(m){DCMORE[m.dataset.dcMore]=1;dcRender();return}
  const u=e.target.closest("[data-dc-undo]");if(u){dcSet(u.dataset.dcUndo,"riattiva");return}
  const row=e.target.closest("[data-dc]");if(!row)return;const id=row.dataset.dc;
  const a=e.target.closest("[data-dc-az]");if(a){const z=a.dataset.dcAz;if(z==="tardi"){DCT=DCT===id?null:id;dcRender();return}dcSet(id,z);return}
  const g=e.target.closest("[data-dc-g]");if(g){const d=new Date(DC.today+"T12:00:00Z");d.setUTCDate(d.getUTCDate()+(+g.dataset.dcG));dcSet(id,"tardi",d.toISOString().slice(0,10))}});
