async function ttSettings(env) { return { ...TT_DEFAULT, ...((await kvGet(env, "tt_settings")) || {}) }; }
function ttClip(s, n) { s = String(s || "").trim(); if (s.length <= n) return s; s = s.slice(0, n); return /[\uD800-\uDBFF]$/.test(s) ? s.slice(0, -1) : s; }
