  const w = b.which === "dom" ? "dom" : "div"; const cur = ov[w] || {};
  if (typeof b.testo === "string") { const s = b.testo.trim().slice(0, w === "dom" ? 500 : 600); if (s) cur.testo = s; else delete cur.testo; }
  if (typeof b.skip === "boolean") cur.skip = b.skip;
