const MAIL_HTML = "<!DOCTYPE html>\n<html lang=\"it\" xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"color-scheme\" content=\"dark light\">\n<meta name=\"supported-color-schemes\" content=\"dark light\">\n<title>Read Geopolitics · {{date_long}}</title>\n<style>\nbody{margin:0;padding:0;background:#0B1117;-webkit-text-size-adjust:100%}\na{color:#86B4EA}\n@media (max-width:620px){.w{width:100%!important}.p{padding-left:18px!important;padding-right:18px!important}.h1{font-size:27px!important;line-height:33px!important}}\n</style>\n</head>\n<body style=\"margin:0;padding:0;background:#0B1117;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">{{preheader}}</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background:#0B1117;\">\n<tr><td align=\"center\" style=\"padding:0;\">\n<table role=\"presentation\" class=\"w\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:600px;max-width:600px;\">\n\n<!-- testata -->\n<tr><td class=\"p\" style=\"padding:22px 24px 14px 24px;border-bottom:1px solid #22313D;\">\n <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n  <td valign=\"middle\"><a href=\"{{cta_url}}\" style=\"text-decoration:none;\"><img src=\"https://www.readgeopolitics.com/img/nl-logo.png\" width=\"168\" height=\"45\" alt=\"Read Geopolitics\" style=\"display:block;border:0;width:168px;height:45px;\"></a></td>\n  <td valign=\"middle\" align=\"right\" style=\"font-family:'SFMono-Regular',Menlo,Consolas,monospace;font-size:11px;letter-spacing:1px;color:#8FA0AE;text-transform:uppercase;\">{{date_long}}</td>\n </tr></table>\n</td></tr>\n\n<!-- titolo -->\n<tr><td class=\"p\" style=\"padding:22px 24px 6px 24px;\">\n <div class=\"h1\" style=\"font-family:Georgia,'Times New Roman',serif;font-size:30px;line-height:36px;font-weight:700;color:#F2EDE4;\">{{headline}}</div>\n {{#subheadline}}<div style=\"font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:17px;line-height:25px;color:#B7C3CE;margin-top:8px;\">{{subheadline}}</div>{{/subheadline}}\n</td></tr>\n\n<!-- podcast: una riga -->\n<tr><td class=\"p\" style=\"padding:12px 24px 18px 24px;\">\n <a href=\"{{podcast.listen_url}}\" style=\"font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:15px;line-height:22px;color:#E8B050;font-weight:700;text-decoration:none;\">🎧 Ascolta il briefing</a><span style=\"font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:14px;color:#8FA0AE;\"> · {{podcast.meta}}</span>\n</td></tr>\n\n<!-- in 60 secondi -->\n<tr><td class=\"p\" style=\"padding:0 24px;\">\n <div style=\"border-top:1px solid #22313D;padding-top:16px;font-family:'SFMono-Regular',Menlo,Consolas,monospace;font-size:12px;letter-spacing:1.5px;color:#86B4EA;text-transform:uppercase;\">In 60 secondi</div>\n <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:6px 0 16px 0;\">\n {{#sixty}}<tr><td valign=\"top\" width=\"22\" style=\"padding:8px 0;font-family:Georgia,serif;font-size:16px;line-height:24px;color:#E8B050;font-weight:700;\">{{n}}</td><td style=\"padding:8px 0;font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:16px;line-height:24px;\"><a href=\"{{url}}\" style=\"color:#DDE4EA;text-decoration:none;\">{{#title}}<b style=\"color:#F2EDE4;\">{{title}}</b> · {{/title}}{{text}} <span style=\"color:#86B4EA;\">›</span></a></td></tr>{{/sixty}}\n </table>\n</td></tr>\n\n<!-- il fatto centrale -->\n<tr><td class=\"p\" style=\"padding:0 24px;\">\n <div style=\"border-top:1px solid #22313D;padding-top:18px;font-family:'SFMono-Regular',Menlo,Consolas,monospace;font-size:12px;letter-spacing:1.5px;color:#86B4EA;text-transform:uppercase;\">La storia del giorno{{#lead.tag}} · {{lead.tag}}{{/lead.tag}}</div>\n <div style=\"height:8px;line-height:8px;font-size:0;\">&nbsp;</div>\n <div style=\"font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:16px;line-height:25px;color:#DDE4EA;\">{{lead.summary}}</div>\n {{#lead.why}}<div style=\"font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:16px;line-height:25px;color:#DDE4EA;margin-top:10px;\"><b style=\"color:#E8B050;\">Perché conta.</b> {{lead.why}}</div>{{/lead.why}}\n</td></tr>\n{{#lead.has_readings}}\n<tr><td class=\"p\" style=\"padding:16px 24px 0 24px;\">\n <div style=\"border-left:3px solid #86B4EA;padding:2px 0 2px 12px;margin-bottom:12px;font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:15px;line-height:23px;color:#DDE4EA;\"><div style=\"font-size:12px;letter-spacing:1px;text-transform:uppercase;color:#86B4EA;font-weight:700;margin-bottom:2px;\">{{lead.pro.label}}</div>{{lead.pro.text}}</div>\n <div style=\"border-left:3px solid #E8B050;padding:2px 0 2px 12px;font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:15px;line-height:23px;color:#DDE4EA;\"><div style=\"font-size:12px;letter-spacing:1px;text-transform:uppercase;color:#E8B050;font-weight:700;margin-bottom:2px;\">{{lead.contro.label}}</div>{{lead.contro.text}}</div>\n</td></tr>\n{{/lead.has_readings}}\n<tr><td class=\"p\" style=\"padding:14px 24px 20px 24px;\">\n <a href=\"{{lead.url}}\" style=\"font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:15px;font-weight:700;color:#86B4EA;text-decoration:none;\">Fonti, sintesi e cosa decide la storia →</a>\n</td></tr>\n\n{{#vote}}\n<tr><td class=\"p\" style=\"padding:0 24px 20px 24px;\">\n <div style=\"border-top:1px solid #22313D;padding-top:16px;font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:16px;line-height:23px;font-weight:700;color:#F2EDE4;\">{{vote.q}}</div>\n <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-top:10px;\"><tr>\n  <td width=\"50%\" style=\"padding:0 4px 0 0;\"><a href=\"{{vote.url_a}}\" style=\"display:block;font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:15px;font-weight:700;line-height:20px;color:#F2EDE4;border:1.5px solid #86B4EA;border-radius:8px;padding:12px 6px;text-align:center;text-decoration:none;\">{{vote.a}}</a></td>\n  <td width=\"50%\" style=\"padding:0 0 0 4px;\"><a href=\"{{vote.url_b}}\" style=\"display:block;font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:15px;font-weight:700;line-height:20px;color:#F2EDE4;border:1.5px solid #E8B050;border-radius:8px;padding:12px 6px;text-align:center;text-decoration:none;\">{{vote.b}}</a></td>\n </tr></table>\n <div style=\"font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:13px;line-height:19px;color:#8FA0AE;margin-top:8px;\">Voto anonimo, un tocco. <a href=\"{{vote.url_n}}\" style=\"color:#B7C3CE;\">Non so</a> · domani il risultato.</div>\n</td></tr>\n{{/vote}}\n\n{{#spiegato}}\n<tr><td class=\"p\" style=\"padding:6px 24px 4px 24px;\">\n <a href=\"{{spiegato.url}}\" style=\"text-decoration:none;\"><span style=\"font-family:'SFMono-Regular',Menlo,Consolas,monospace;font-size:12px;letter-spacing:1.5px;color:#E8B050;text-transform:uppercase;\">Lo Spiegato</span><br><span style=\"font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:16px;line-height:23px;font-weight:700;color:#F2EDE4;\">{{spiegato.q}}</span></a>\n</td></tr>\n{{/spiegato}}\n\n<!-- invito -->\n<tr><td class=\"p\" style=\"padding:18px 24px 26px 24px;\">\n <a href=\"{{cta_url}}\" style=\"display:block;font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:17px;font-weight:700;line-height:22px;color:#0B1117;background:#E8B050;border-radius:10px;padding:15px 10px;text-align:center;text-decoration:none;\">Apri il briefing completo →</a>\n</td></tr>\n\n<!-- piede -->\n<tr><td class=\"p\" style=\"padding:16px 24px 30px 24px;border-top:1px solid #22313D;font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:12.5px;line-height:19px;color:#8FA0AE;\">\n Ti è utile? <a href=\"{{forward_url}}\" style=\"color:#B7C3CE;\">Inoltrala</a>: ci si iscrive gratis.<br>\n Read Geopolitics · il mondo in 15 minuti · <a href=\"https://www.instagram.com/read.geopolitics/\" style=\"color:#B7C3CE;\">Instagram</a> · <a href=\"https://t.me/readgeopolitics\" style=\"color:#B7C3CE;\">Telegram</a> · <a href=\"https://www.tiktok.com/@readgeopolitics\" style=\"color:#B7C3CE;\">TikTok</a><br>\n <a href=\"{{privacy_url}}\" style=\"color:#8FA0AE;\">Informativa privacy</a> · <a href=\"{{unsubscribe_url}}\" style=\"color:#8FA0AE;\">Disiscriviti</a>\n</td></tr>\n\n</table>\n</td></tr>\n</table>\n</body>\n</html>\n"; // v104: senza «Anche oggi» (ripeteva In 60 secondi); le righe di In 60 secondi aprono il sito
