    const r = await mailSend(env, [{ from: cfg.from, to: [x.email], reply_to: cfg.reply_to, subject: "Re: la tua segnalazione " + x.ref + " a Read Geopolitics", html, text: txt + "\n\n— Read Geopolitics\nhttps://www.readgeopolitics.com\n\nCi avevi scritto:\n" + q }], "fbr-" + x.id + "-" + txt.length);
