async function spFire(env, text) { // avvia subito la routine Spiegati (API trigger collegato dal pannello)
  const g = (await kvGet(env, "sp:routine")) || {};
  if (!g.id || !g.token) return "routine non collegata: la richiesta resta in coda per il prossimo giro";
  try {
    const r = await fetch("https://api.anthropic.com/v1/claude_code/routines/" + encodeURIComponent(g.id) + "/fire", { method: "POST", headers: { authorization: "Bearer " + g.token, "anthropic-version": "2023-06-01", "content-type": "application/json" }, body: JSON.stringify({ text }), signal: AbortSignal.timeout(8000) });
    return r.ok ? "avviata" : "errore " + r.status;
  } catch (e) { return "errore di rete"; }
}
